<section><div class="page-heading"><div><p class="eyebrow">Accounts</p><h1>Merchants</h1><p class="muted">Search accounts, inspect their stores, and control platform access.</p></div><span><?= e($result['total']) ?> merchants</span></div><form class="admin-filters" method="get" action="/sa/merchants"><input type="search" name="q" value="<?= e($filters['q']) ?>" placeholder="Name, email, store, or slug" aria-label="Search merchants"><select name="status" aria-label="Merchant status"><option value="">All statuses</option><?php foreach(['ACTIVE','SUSPENDED']as$status):?><option value="<?= e($status) ?>" <?= $filters['status']===$status?'selected':'' ?>><?= e(ucfirst(strtolower($status))) ?></option><?php endforeach ?></select><button class="button secondary">Filter</button></form><section class="panel flush"><div class="table-wrap"><table><thead><tr><th>Merchant</th><th>Status</th><th>Stores</th><th>Verified</th><th>Last login</th><th></th></tr></thead><tbody><?php foreach($result['items']as$row):?><tr><td><strong><?= e($row['name']) ?></strong><small><?= e($row['email']) ?></small></td><td><span class="badge <?= strtolower($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= e($row['store_count']) ?> <small><?= e($row['active_store_count']) ?> active</small></td><td><?= $row['email_verified_at']?'Yes':'No' ?></td><td><?= e($row['last_login_at']??'Never') ?></td><td><a class="button compact secondary" href="/sa/merchants/<?= e($row['id']) ?>">Inspect</a></td></tr><?php endforeach ?></tbody></table></div><?php if(!$result['items']):?><div class="empty-inline padded">No merchants match these filters.</div><?php endif ?></section><?php $base=['q'=>$filters['q'],'status'=>$filters['status']];?><nav class="admin-pagination" aria-label="Merchant pages"><?php if($result['page']>1):?><a href="?<?= e(http_build_query($base+['page'=>$result['page']-1])) ?>">← Previous</a><?php endif ?><span>Page <?= e($result['page']) ?> of <?= e($result['pages']) ?></span><?php if($result['page']<$result['pages']):?><a href="?<?= e(http_build_query($base+['page'=>$result['page']+1])) ?>">Next →</a><?php endif ?></nav></section>
